using CouponBook.Api.Dtos;using CouponBook.Business.Auth;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;namespace CouponBook.Api.Controllers;
[ApiController][Route("api/me")][Authorize]public class MeController:ControllerBase{private readonly IAccountService _a;public MeController(IAccountService a)=>_a=a;private int U=>int.Parse(User.FindFirst("sub")!.Value);[HttpGet]public async Task<IActionResult> Get(){var r=await _a.GetProfileAsync(U);return r.Succeeded?Ok(r.Value):NotFound();}[HttpPut]public async Task<IActionResult> Put(UpdateProfileRequest q){var r=await _a.UpdateProfileAsync(U,q.FullName,q.Email,q.Language);return r.Succeeded?Ok(r.Value):BadRequest(new{code=r.ErrorCode,errors=r.Errors});}}
